insert into public.products (name, description, price, category, image_url, stock, tags, specifications)
values
  ('Wireless Noise-Canceling Headphones', 'Premium over-ear headphones featuring hybrid active noise cancellation, 40mm dynamic drivers, and a 30-hour battery life on a single charge. Memory-foam ear cushions provide all-day comfort, while Bluetooth 5.3 with multipoint pairing keeps you connected to two devices at once. A built-in transparency mode lets you hear your surroundings without removing the headset.', 249.99, 'Electronics', '/images/products/headphones.png', 45, ARRAY['audio', 'wireless', 'headphones'], '{"brand":"SoundWave","sku":"SW-NC100","weight":"250g","dimensions":"18 x 17 x 8 cm","material":"Aluminum / Memory Foam","color":"Matte Black","warranty":"2 years"}'::jsonb),
  ('Smart Watch Series 7', 'A sleek smartwatch with a 1.9-inch always-on AMOLED display, continuous heart-rate and SpO2 monitoring, and built-in GPS tracking. Track over 80 sport modes, receive smartphone notifications, and enjoy a 5-day battery life on a single charge. Water resistance up to 50 meters makes it suitable for swimming and showering.', 299.00, 'Electronics', '/images/products/smartwatch.png', 30, ARRAY['wearable', 'fitness', 'smart'], '{"brand":"PulseTech","sku":"PT-SW7","weight":"38g","dimensions":"44 x 38 x 11 mm","material":"Aluminum / Silicone band","color":"Midnight Blue","warranty":"1 year"}'::jsonb),
  ('Minimalist Leather Backpack', 'Handcrafted from full-grain vegetable-tanned leather, this minimalist backpack features a padded 15-inch laptop compartment, hidden anti-theft pockets, and solid brass hardware. The structured silhouette ages beautifully over time, developing a unique patina. Adjustable shoulder straps ensure all-day carrying comfort.', 159.50, 'Fashion', '/images/products/backpack.png', 25, ARRAY['leather', 'bag', 'travel'], '{"brand":"Atelier Lane","sku":"AL-MB15","weight":"1.2kg","dimensions":"42 x 30 x 14 cm","material":"Full-grain leather / Brass","color":"Tan","warranty":"1 year"}'::jsonb),
  ('Running Performance Sneakers', 'Lightweight breathable mesh sneakers engineered for daily runs, featuring a responsive foam midsole and a durable rubber outsole with multi-directional traction lugs. The padded collar and tongue provide a secure, comfortable fit, while reflective accents improve low-light visibility. Designed for neutral runners seeking all-day comfort.', 119.95, 'Fashion', '/images/products/sneakers.png', 60, ARRAY['shoes', 'running', 'sport'], '{"brand":"StridePro","sku":"SP-RN42","weight":"280g","dimensions":"US 7-13 available","material":"Mesh / Rubber / EVA foam","color":"Storm Grey","warranty":"6 months"}'::jsonb),
  ('Ceramic Pour-Over Coffee Set', 'An elegant ceramic pour-over set including a ribbed dripper and a 600ml carafe, designed for even extraction and heat retention. The minimalist matte glaze complements any kitchen aesthetic, and the ergonomic handle offers a steady, drip-free pour. Compatible with standard size-2 cone filters.', 84.99, 'Home', '/images/products/coffee_set.png', 40, ARRAY['coffee', 'kitchen', 'ceramic'], '{"brand":"Brew & Co","sku":"BC-PO600","weight":"700g","dimensions":"15 x 10 x 12 cm","material":"Stoneware ceramic","color":"Matte White","warranty":"1 year"}'::jsonb),
  ('Smart Home Speaker', 'A voice-controlled smart speaker delivering rich 360-degree room-filling sound with deep bass response. Built-in far-field microphones recognize voice commands from across the room, and the integrated smart home hub controls lights, thermostats, and security devices. Stream music from your favorite services with seamless multi-room audio support.', 129.00, 'Electronics', '/images/products/smart_speaker.png', 35, ARRAY['speaker', 'smart home', 'audio'], '{"brand":"NestAudio","sku":"NA-SH1","weight":"820g","dimensions":"14 x 14 x 14 cm","material":"Fabric / Recycled plastic","color":"Chalk","warranty":"1 year"}'::jsonb),
  ('Cotton Linen Throw Blanket', 'A soft, breathable cotton-linen blend throw blanket woven on traditional looms for a textured, natural finish. Perfect for draping over sofas, beds, or armchairs, it provides lightweight warmth year-round. The pre-washed fabric gains softness with every wash without pilling.', 64.00, 'Home', '/images/products/throw_blanket.png', 50, ARRAY['blanket', 'home decor', 'cozy'], '{"brand":"CozyNest","sku":"CN-CL50","weight":"900g","dimensions":"130 x 170 cm","material":"55% Cotton / 45% Linen","color":"Oatmeal","warranty":"No warranty"}'::jsonb),
  ('Bestseller Fiction Novel', 'A gripping, critically acclaimed novel that weaves together themes of family, memory, and resilience across multiple generations. The prose is both lyrical and propulsive, keeping readers turning pages late into the night. Winner of the National Book Award and a New York Times bestseller.', 18.99, 'Books', '/images/products/fiction_novel.png', 100, ARRAY['fiction', 'bestseller', 'reading'], '{"brand":"Penbridge Press","sku":"PB-FN001","weight":"420g","dimensions":"21 x 14 x 3 cm","material":"Paperback / FSC paper","color":"Cover varies","warranty":"No warranty"}'::jsonb),
  ('Yoga Mat Premium', 'An eco-friendly TPE yoga mat with a dual-layer non-slip surface and printed alignment guides to support correct posture in every pose. At 6mm thick, it cushions joints during high-impact flows while remaining lightweight enough to carry to the studio. Free from PVC, latex, and toxic dyes.', 55.00, 'Sports', '/images/products/yoga_mat.png', 70, ARRAY['yoga', 'fitness', 'mat'], '{"brand":"ZenFlow","sku":"ZF-YM6","weight":"1.0kg","dimensions":"183 x 61 x 0.6 cm","material":"TPE (Thermoplastic Elastomer)","color":"Sage Green","warranty":"1 year"}'::jsonb),
  ('Adjustable Dumbbell Set', 'A space-saving adjustable dumbbell pair that replaces an entire rack, dialing from 5 to 50 pounds per hand in 2.5-pound increments. The quick-select dial locks the plates securely in place, and the contoured ergonomic grip reduces hand fatigue. Ideal for home gyms where floor space is limited.', 349.99, 'Sports', '/images/products/dumbbell_set.png', 20, ARRAY['weights', 'gym', 'fitness'], '{"brand":"IronCore","sku":"IC-AD50","weight":"Varies 5-50 lbs","dimensions":"40 x 20 x 18 cm (each)","material":"Steel / Polypropylene","color":"Black / Silver","warranty":"2 years"}'::jsonb),
  ('Mechanical Keyboard', 'A tactile mechanical keyboard with hot-swappable switches, per-key RGB backlighting, and a sturdy aluminum-alloy frame. Pre-lubed linear switches deliver a smooth, quiet typing experience, while the doubleshot PBT keycaps resist shine and wear over time. USB-C and Bluetooth connectivity support up to three paired devices.', 149.99, 'Electronics', '/images/products/mechanical_keyboard.png', 28, ARRAY['keyboard', 'gaming', 'productivity'], '{"brand":"KeyForge","sku":"KF-MK87","weight":"1.1kg","dimensions":"36 x 14 x 4 cm","material":"Aluminum / PBT","color":"Space Gray","warranty":"2 years"}'::jsonb),
  ('Organic Cotton T-Shirt', 'A soft, sustainable t-shirt knit from GOTS-certified organic cotton with a relaxed, everyday fit. The mid-weight 220 GSM fabric holds its shape wash after wash, and the reinforced collar resists stretching. Garment-dyed in small batches for a lived-in, slightly heathered finish.', 34.99, 'Fashion', '/images/products/cotton_tshirt.png', 80, ARRAY['clothing', 'organic', 'casual'], '{"brand":"PureThread","sku":"PT-CT22","weight":"180g","dimensions":"XS-XXL available","material":"100% Organic cotton","color":"Heather Oat","warranty":"No warranty"}'::jsonb),
  ('Aromatherapy Diffuser', 'An ultrasonic essential oil diffuser with a 300ml tank, seven ambient LED light settings, and whisper-quiet operation under 25 decibels. The fine cool-mist output preserves the therapeutic properties of your oils, while the auto-shutoff feature ensures safety when water runs low. Run time up to 10 hours per fill.', 42.50, 'Home', '/images/products/diffuser.png', 55, ARRAY['wellness', 'home', 'aromatherapy'], '{"brand":"MistLab","sku":"ML-DF300","weight":"380g","dimensions":"16 x 16 x 14 cm","material":"BPA-free Polypropylene","color":"Natural Wood Grain","warranty":"1 year"}'::jsonb),
  ('Self-Help Productivity Book', 'A practical, science-backed guide to building lasting habits and maximizing daily output without burnout. Drawing on research in behavioral psychology and neuroscience, it offers actionable frameworks for goal-setting, focus, and deep work. Includes worksheets and a 30-day implementation plan.', 22.95, 'Books', '/images/products/productivity_book.png', 75, ARRAY['self-help', 'productivity', 'non-fiction'], '{"brand":"MindShift Press","sku":"MS-PB30","weight":"390g","dimensions":"21 x 14 x 2.5 cm","material":"Paperback / FSC paper","color":"Cover varies","warranty":"No warranty"}'::jsonb),
  ('Basketball Pro', 'An official size-7 basketball engineered with a high-abrasion composite leather cover for superior grip and durability on both indoor and outdoor courts. The deep-channel design improves ball control and shooting accuracy, while the butyl bladder retains air pressure season after season. NFHS-approved for competitive play.', 39.99, 'Sports', '/images/products/basketball.png', 45, ARRAY['basketball', 'sports', 'outdoor'], '{"brand":"CourtKing","sku":"CK-BB7","weight":"620g","dimensions":"Size 7 (29.5 in)","material":"Composite leather / Butyl bladder","color":"Orange / Black","warranty":"1 year"}'::jsonb);
insert into public.email_templates (name, subject, body, type)
values
  ('Cart Abandonment', 'You left something behind!', 'Hi there,<br><br>You still have items in your cart. Complete your order now and enjoy a seamless AI-powered shopping experience.<br><br><a href="{{cart_url}}">View Cart</a><br><br>Thanks,<br>AI VYOM Team', 'cart_abandonment'),
  ('Delivery Update', 'Your order is on its way!', 'Hi {{full_name}},<br><br>Great news! Your order <strong>#{{order_id}}</strong> has been {{status}}. Track your package for live updates.<br><br><a href="{{order_url}}">Track Order</a><br><br>Thanks,<br>AI VYOM Team', 'delivery'),
  ('Retention Win-Back', 'We miss you!', 'Hi there,<br><br>It has been a while since your last visit. Here are some new arrivals we think you will love, curated by our AI assistant.<br><br><a href="{{products_url}}">Shop New Arrivals</a><br><br>Thanks,<br>AI VYOM Team', 'retention');
